/* modelvet.h: public header for the modelvet structural validator.
 * SPDX-License-Identifier: MIT. Copyright (c) 2026 AgenC (tetsuo-ai).
 *
 * modelvet answers one question: is this model file structurally safe to
 * load? The library is freestanding C11, never allocates, and works in one
 * caller-provided arena. A malformed file is normal operation, not an
 * error: the status stays MVET_OK and the report verdict says REJECT.
 * Status codes are reserved for API misuse and arena exhaustion. */

#ifndef MODELVET_H
#define MODELVET_H

#include <stddef.h>
#include <stdint.h>

/* Version parts stay #defines so embedders can test them with the
 * preprocessor; enums are invisible to #if. */
#define MVET_VERSION_MAJOR 0u
#define MVET_VERSION_MINOR 1u
#define MVET_VERSION_PATCH 0u

/* Packed as major * 1000000 + minor * 1000 + patch (sqlite convention),
 * so 0.0.2 packs to 2. The multipliers are defined only here. */
#define MVET_VERSION_NUMBER \
    (MVET_VERSION_MAJOR * 1000000u + MVET_VERSION_MINOR * 1000u + MVET_VERSION_PATCH)

/* Compile-time caps on every count and length a hostile file controls.
 * All are #defines, not enums, because embedders override them on the
 * compiler command line and the arena bound below must track the override
 * in the preprocessor. Defaults come from a survey of real published
 * models; raising a cap only raises the arena bound, never the API. */

#ifndef MVET_MAX_KV_COUNT
#define MVET_MAX_KV_COUNT 1024u /* real models carry < 100 metadata keys */
#endif

/* 405B-class LLM GGUFs declare ~1100-1500 tensors, but ComfyUI-ecosystem
 * diffusion exports run far higher (seen at 4444). */
#ifndef MVET_MAX_TENSORS
#define MVET_MAX_TENSORS 8192u
#endif

#ifndef MVET_MAX_KEY_BYTES
#define MVET_MAX_KEY_BYTES 256u /* real keys are < 64 bytes */
#endif

/* Tensor names have no format-level limit; llama.cpp's own loader
 * enforces < 64 bytes (its fixed name buffer), but ComfyUI-ecosystem
 * GGUFs legitimately carry longer transformers-namespace names (seen at
 * 64 in Google's Gemma-3 QAT export). Set 63 for strict llama.cpp
 * loader parity. */
#ifndef MVET_MAX_NAME_BYTES
#define MVET_MAX_NAME_BYTES 256u
#endif

#ifndef MVET_MAX_STRING_BYTES
#define MVET_MAX_STRING_BYTES (1u << 20) /* chat templates reach tens of KB */
#endif

#ifndef MVET_MAX_DIMS
#define MVET_MAX_DIMS 4u /* ggml's own hard limit (GGML_MAX_DIMS) */
#endif

/* Documentation only: GGUF forbids arrays of arrays, so the validator
 * rejects any nesting regardless of this value. */
#ifndef MVET_MAX_ARRAY_DEPTH
#define MVET_MAX_ARRAY_DEPTH 1u
#endif

#ifndef MVET_MAX_ARRAY_ELEMS
#define MVET_MAX_ARRAY_ELEMS (1u << 22) /* vocab ~256k, merge lists ~1M */
#endif

#ifndef MVET_MAX_ALIGNMENT
#define MVET_MAX_ALIGNMENT 65536u /* real writers emit 32..4096 */
#endif

#ifndef MVET_MAX_KV_TOTAL_BYTES
#define MVET_MAX_KV_TOTAL_BYTES (1u << 28) /* big tokenizer sections: ~20 MB */
#endif

/* safetensors caps. The header-bytes default equals the canonical Rust
 * implementation's MAX_HEADER_SIZE exactly (see tools/st-pin.env), so
 * the default profile introduces no cap-induced false positives against
 * canonical-accepted files. The other three are modelvet policy caps. */

#ifndef MVET_MAX_ST_HEADER_BYTES
#define MVET_MAX_ST_HEADER_BYTES 100000000u
#endif

#ifndef MVET_MAX_ST_TENSORS
#define MVET_MAX_ST_TENSORS 8192u
#endif

#ifndef MVET_MAX_ST_METADATA_ENTRIES
#define MVET_MAX_ST_METADATA_ENTRIES 1024u
#endif

#ifndef MVET_MAX_ST_NAME_BYTES
#define MVET_MAX_ST_NAME_BYTES 256u
#endif

/* Arena allocation granularity and exact worst-case demand. Each key or
 * tensor-name index stores two size_t words. Both index arrays have sizes
 * divisible by the alignment on supported targets, so only the first
 * nonempty carve can require padding. The default is 147,463 bytes on a
 * 64-bit target. The documented 64 KiB profile uses 49,159 bytes. */
enum {
    MVET_ARENA_ALIGN = 8,
    MVET_GGUF_INDEX_WORDS = 2,
    MVET_ST_EXTENT_WORDS = 2,
    MVET_REPORT_DETAIL_COUNT = 2
};

#define MVET_GGUF_ARENA_WORST_BYTES                                                             \
    (sizeof(size_t) * (size_t)MVET_GGUF_INDEX_WORDS *                                           \
         ((size_t)MVET_MAX_KV_COUNT + (size_t)MVET_MAX_TENSORS) +                               \
     (((MVET_MAX_KV_COUNT) != 0u || (MVET_MAX_TENSORS) != 0u) ? (size_t)(MVET_ARENA_ALIGN - 1u) \
                                                              : (size_t)0u))

/* safetensors worst-case arena demand: one span per root key (tensor
 * names plus one __metadata__ key), one span per metadata key, and one
 * u64 start/end extent pair per tensor for sorted-offset validation.
 * Every element size is a multiple of the arena alignment, so only the
 * first carve can need padding. 278,551 bytes at 64-bit defaults; the
 * documented 64 KiB profile (-DMVET_MAX_ST_TENSORS=1536u
 * -DMVET_MAX_ST_METADATA_ENTRIES=512u) needs 57,367 bytes. */
#define MVET_ST_ARENA_WORST_BYTES                                                    \
    (sizeof(size_t) * (size_t)MVET_GGUF_INDEX_WORDS *                                \
         ((size_t)MVET_MAX_ST_TENSORS + 1u + (size_t)MVET_MAX_ST_METADATA_ENTRIES) + \
     sizeof(uint64_t) * (size_t)MVET_ST_EXTENT_WORDS * (size_t)MVET_MAX_ST_TENSORS + \
     (size_t)(MVET_ARENA_ALIGN - 1u))

/* API status. Never used for file verdicts: a malformed file is MVET_OK
 * with MVET_VERDICT_REJECT in the report. */
typedef enum {
    MVET_OK = 0,
    MVET_ERR_ARG = -1,  /* NULL or invalid argument */
    MVET_ERR_ARENA = -2 /* arena too small for this input's counts */
} mvet_status_t;

/* Verdicts. REJECT is 0 so an all-zero report is fail-closed. */
typedef enum {
    MVET_VERDICT_REJECT = 0,
    MVET_VERDICT_ACCEPT = 1
} mvet_verdict_t;

/* Violation codes: the reason a file was rejected. Append-only ABI with
 * explicit values; codes are never renumbered or reused. Groups leave
 * numbering gaps for future codes. The comment on each code states the
 * meaning of report detail[0] (d0) and detail[1] (d1).
 *
 * Codes marked "policy" are deliberate modelvet strictness beyond what
 * ggml's own reader enforces; everything else mirrors the de facto
 * format. */
typedef enum {
    MVET_V_NONE = 0,

    /* Input ended before a required field. d0 bytes needed, d1 left. */
    MVET_V_TRUNCATED = 1,

    /* Magic and version. */
    MVET_V_MAGIC = 100,               /* d0 observed 4 bytes LE, d1 'GGUF' */
    MVET_V_VERSION_UNSUPPORTED = 101, /* zero or too new; d0 got, d1 max */
    MVET_V_VERSION_LEGACY = 102,      /* GGUFv1, rejected; d0 got, d1 0 */
    MVET_V_VERSION_ENDIAN = 103,      /* byte-swapped write; d0 got, d1 0 */

    /* Header counts. d0 declared count, d1 cap. */
    MVET_V_TENSOR_COUNT_RANGE = 110,
    MVET_V_KV_COUNT_RANGE = 111,

    /* Metadata key-value walk. */
    MVET_V_KEY_EMPTY = 200,           /* d0 0, d1 0 */
    MVET_V_KEY_LEN_CAP = 201,         /* d0 declared length, d1 cap */
    MVET_V_KEY_UTF8 = 202,            /* d0 bad byte index in key, d1 0 */
    MVET_V_KEY_DUPLICATE = 203,       /* d0 first, d1 second key offset */
    MVET_V_KV_TYPE_RANGE = 204,       /* d0 tag, d1 max tag */
    MVET_V_KV_ARRAY_TYPE_RANGE = 205, /* d0 inner tag, d1 max tag */
    MVET_V_KV_ARRAY_NESTED = 206,     /* array of arrays; d0 tag, d1 0 */
    MVET_V_KV_ARRAY_ELEMS_CAP = 207,  /* d0 declared count, d1 cap */
    MVET_V_KV_BOOL_BYTE = 208,        /* policy; d0 byte value, d1 1 */
    MVET_V_KV_TOTAL_BYTES_CAP = 209,  /* d0 projected encoded bytes, d1 cap */
    MVET_V_STR_LEN_CAP = 210,         /* d0 declared length, d1 cap */
    MVET_V_STR_UTF8 = 211,            /* d0 bad byte index, d1 0 */

    /* general.alignment. */
    MVET_V_ALIGN_TYPE = 220,  /* d0 tag observed, d1 UINT32 tag */
    MVET_V_ALIGN_VALUE = 221, /* zero, non-pow2 or over cap;
                               * d0 value, d1 cap */

    /* Tensor info records. */
    MVET_V_NAME_LEN = 300,                  /* d0 declared length, d1 cap */
    MVET_V_NAME_UTF8 = 301,                 /* d0 bad byte index, d1 0 */
    MVET_V_NAME_DUPLICATE = 302,            /* d0 first, d1 second name offset */
    MVET_V_TENSOR_DIMS_CAP = 303,           /* d0 n_dims, d1 cap */
    MVET_V_TENSOR_NE_RANGE = 304,           /* negative or zero dimension;
                                             * d0 raw value, d1 dimension index */
    MVET_V_TENSOR_NE_OVERFLOW = 305,        /* element product >= INT64_MAX;
                                             * offset is offending dimension;
                                             * d0 raw value, d1 dimension index */
    MVET_V_TENSOR_DTYPE_RANGE = 306,        /* d0 dtype, d1 max */
    MVET_V_TENSOR_DTYPE_UNSUPPORTED = 307,  /* dead ggml slot; d0 dtype */
    MVET_V_TENSOR_BLOCK_DIVISIBILITY = 308, /* d0 dimensions[0], d1 block */
    MVET_V_TENSOR_OFFSET_MISMATCH = 309,    /* not densely packed; d0 declared,
                                             * d1 expected offset */
    MVET_V_TENSOR_SIZE_OVERFLOW = 310,      /* size arithmetic overflow;
                                             * d0 and d1 are exact operands */
    MVET_V_TENSOR_DATA_EXTENT = 311,        /* d0 required end, d1 buffer length */

    /* Whole file. */
    MVET_V_TRAILING_BYTES = 400, /* policy; d0 expected end, d1 buffer length */

    /* safetensors frame and header JSON. "policy" marks modelvet
     * strictness beyond the canonical Rust implementation (pinned in
     * tools/st-pin.env); everything else mirrors it. MVET_V_TRUNCATED
     * covers a file too short for the frame. */
    MVET_V_ST_HEADER_LEN_CAP = 500, /* d0 declared length, d1 cap */
    MVET_V_ST_JSON_SYNTAX = 510,    /* d0 observed byte, d1 0 */
    MVET_V_ST_STR_UTF8 = 511,       /* d0 bad byte index in string, d1 0 */
    MVET_V_ST_STR_ESCAPE = 512,     /* d0 escape byte, d1 0 */
    MVET_V_ST_KEY_ESCAPE = 513,     /* policy; d0 escape byte, d1 0 */
    MVET_V_ST_NUMBER = 514,         /* malformed or past u64; d0 0, d1 0 */
    MVET_V_ST_NAME_LEN = 515,       /* policy; d0 length, d1 cap */
    MVET_V_ST_KEY_DUPLICATE = 516,  /* policy; d0 first, d1 second offset */

    /* safetensors caps. d0 count, d1 cap. */
    MVET_V_ST_TENSOR_COUNT_CAP = 520,   /* policy */
    MVET_V_ST_METADATA_COUNT_CAP = 521, /* policy */

    /* safetensors tensor entries. */
    MVET_V_ST_TENSOR_FIELDS = 530, /* unknown, repeated, or missing field;
                                    * d0 seen field mask, d1 required 7 */
    MVET_V_ST_DTYPE_UNKNOWN = 531, /* d0 0, d1 0 */
    MVET_V_ST_OFFSETS_ARITY = 532, /* d0 elements seen, d1 2 */

    /* safetensors data layout. The sorted-extent rules (544, 545)
     * report offset = data region start, their governing boundary. */
    MVET_V_ST_OFFSET_ORDER = 540,      /* end before begin; d0 begin, d1 end */
    MVET_V_ST_SIZE_OVERFLOW = 541,     /* d0 and d1 are exact operands */
    MVET_V_ST_SIZE_MISALIGNED = 542,   /* sub-byte total; d0 bits, d1 8 */
    MVET_V_ST_SIZE_MISMATCH = 543,     /* d0 declared bytes, d1 computed */
    MVET_V_ST_OFFSET_CONTIGUITY = 544, /* d0 declared start, d1 expected */
    MVET_V_ST_DATA_EXTENT = 545        /* d0 validated end, d1 region size */
} mvet_violation_t;

/* The verdict report. Fixed-width fields only (no enum-typed members) so
 * the layout is a stable ABI. An all-zero report reads as REJECT with no
 * violation recorded: fail closed. offset is where the violation becomes
 * decidable. Direct-field rules point at the field start, UTF-8 rules at the
 * bad byte, duplicate rules at the second value, and derived layout rules at
 * their governing boundary. detail[] semantics are per violation code. */
typedef struct {
    uint32_t verdict;   /* mvet_verdict_t */
    uint32_t violation; /* mvet_violation_t; MVET_V_NONE on ACCEPT */
    uint64_t offset;
    uint64_t detail[MVET_REPORT_DETAIL_COUNT];
} mvet_report_t;

/* Caller-owned working memory. Transparent so it can live on the stack or
 * embed in a parent struct. used is the high-water mark after a verify
 * call; the library never touches memory outside [base, base + capacity). */
typedef struct {
    uint8_t *base;
    size_t capacity;
    size_t used;
} mvet_arena_t;

/* Returns the packed library version, equal to MVET_VERSION_NUMBER of the
 * translation unit the library was built from. Pure. */
uint32_t mvet_version(void);

/* Binds caller-owned memory to the arena. memory designates capacity writable
 * bytes for the lifetime of each verification call and may be NULL only when
 * capacity is zero. The memory must not overlap an input buffer, report, or
 * arena object used in that call. Fails with MVET_ERR_ARG for an invalid
 * pointer pair without modifying a non-NULL arena. */
mvet_status_t mvet_arena_bind(mvet_arena_t *arena, void *memory, size_t capacity);

/* Verifies one whole-buffer GGUF file. A non-NULL report is cleared before
 * every other argument is inspected. The first violation replaces that
 * fail-closed state, or success marks ACCEPT. buffer may be NULL only when
 * length is zero. An arena of MVET_GGUF_ARENA_WORST_BYTES capacity suffices
 * for any input that passes the caps. Fails with MVET_ERR_ARG for invalid
 * arguments and MVET_ERR_ARENA for insufficient working memory. report,
 * arena, buffer, and the arena's storage must not overlap. A writable report
 * stays fail-closed on either API error. */
mvet_status_t
mvet_gguf_verify(mvet_report_t *report, mvet_arena_t *arena, const void *buffer, size_t length);

/* Verifies one whole-buffer safetensors file against the canonical
 * format contract (pinned in tools/st-pin.env) plus the documented
 * policy strictness. Same argument and failure contract as
 * mvet_gguf_verify; an arena of MVET_ST_ARENA_WORST_BYTES capacity
 * suffices for any input that passes the caps. */
mvet_status_t
mvet_st_verify(mvet_report_t *report, mvet_arena_t *arena, const void *buffer, size_t length);

#endif /* MODELVET_H */
